'use client'

import { useEffect, useMemo, useState } from 'react'
import { Area, AreaChart, CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis } from 'recharts'
import { Activity, ArrowDown, ArrowRight, Check, ChevronLeft, ChevronRight, CircleHelp, Code2, Gauge, GitBranch, Languages, Lightbulb, Network, Pause, Play, RotateCcw, Sparkles, Target, TrendingDown, Trophy, Zap } from 'lucide-react'
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Progress } from '@/components/ui/progress'
import { Separator } from '@/components/ui/separator'
import { Slider } from '@/components/ui/slider'
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Textarea } from '@/components/ui/textarea'
import { manualNetwork, format, parseParameters, quiz, starterCode, trainLinear, validateCode, type History } from '@/lib/simulation'

const nav = [{ label: 'Apprendre', icon: Network }, { label: 'Expérimenter', icon: Code2 }, { label: 'Visualiser le modèle', icon: Activity }, { label: 'Vérifier mes connaissances', icon: CircleHelp }]

function Metric({ label, value, tone = 'blue' }: { label: string; value: string; tone?: string }) {
  const toneClasses = { blue: 'bg-blue-50/60 text-blue-800', violet: 'bg-violet-50/60 text-violet-800', orange: 'bg-orange-50/60 text-orange-800', emerald: 'bg-emerald-50/60 text-emerald-800' }[tone] ?? 'bg-slate-50 text-slate-800'
  return <div className={`rounded-xl border p-3 ${toneClasses}`}><p className="text-xs font-semibold">{label}</p><p className="mt-1 font-mono text-lg font-semibold">{value}</p></div>
}

function NetworkDiagram({ state }: { state: ReturnType<typeof trainLinear>[number] }) {
  const active = state.step > 0
  return <div className="relative overflow-hidden rounded-2xl border bg-slate-950 px-5 py-7 text-white shadow-inner">
    <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_20%,rgba(59,130,246,.18),transparent_32%),radial-gradient(circle_at_75%_80%,rgba(139,92,246,.15),transparent_35%)]" />
    <div className="relative flex items-center justify-between gap-3 sm:gap-7">
      <div className="z-10 flex flex-col items-center gap-2"><div className={`grid size-16 place-items-center rounded-full border-2 border-blue-400 bg-blue-500/20 font-mono text-lg ${active ? 'shadow-[0_0_24px_rgba(96,165,250,.7)]' : ''}`}>x</div><span className="text-xs text-slate-300">entrée = 2</span></div>
      <div className="relative min-w-16 flex-1"><div className="h-1 rounded-full bg-blue-400/70" /><div className="absolute -top-6 left-1/2 -translate-x-1/2 rounded bg-slate-800 px-2 py-1 font-mono text-xs text-blue-200">w = {format(state.w)}</div><ArrowRight className="absolute -right-2 -top-2 text-blue-300" /></div>
      <div className="z-10 flex flex-col items-center gap-2"><div className="grid size-16 place-items-center rounded-full border-2 border-violet-400 bg-violet-500/20 font-mono text-lg">Σ</div><span className="text-xs text-slate-300">+ b = {format(state.b)}</span></div>
      <div className="relative min-w-10 flex-1"><div className="h-1 rounded-full bg-violet-400/70" /><ArrowRight className="absolute -right-2 -top-2 text-violet-300" /></div>
      <div className="z-10 flex flex-col items-center gap-2"><div className={`grid size-16 place-items-center rounded-full border-2 border-emerald-400 bg-emerald-500/20 font-mono text-lg ${active ? 'shadow-[0_0_24px_rgba(52,211,153,.6)]' : ''}`}>{format(state.prediction)}</div><span className="text-xs text-slate-300">prédiction</span></div>
    </div>
    <div className="relative mt-8 flex items-center justify-center gap-3 text-xs text-slate-300"><ArrowDown className="text-orange-300" /><span>erreur = {format(state.prediction - 1)} · perte = {format(state.loss)} · gradient w = {format(state.gradW)}</span></div>
  </div>
}

function ManualActivity({ onContinue, onRestart, language }: { onContinue: () => void; onRestart: () => void; language: Language }) {
  const [step, setStep] = useState(0)
  const [exerciseVersion, setExerciseVersion] = useState(0)
  const nn = useMemo(() => manualNetwork(exerciseVersion), [exerciseVersion])
  const [answers, setAnswers] = useState<Record<number, string>>({})
  const steps = [
    { title: 'Propagation avant', text: 'Calcule chaque valeur dans l’ordre : d’abord la combinaison, puis la sigmoïde, puis la prédiction.', values: [['z₁ = w₁ × x + b₁', `${format(nn.w1)} × 2 + ${format(nn.b1)}`], ['h = sigmoid(z₁)', format(nn.h)], ['ŷ = w₂ × h + b₂', format(nn.prediction)]], question: `Avec w₁ = ${format(nn.w1)}, x = ${nn.x} et b₁ = ${format(nn.b1)}, quelle est la valeur de z₁ ?`, options: [`z₁ = ${format(nn.z1)}`, `z₁ = ${format(nn.w1)}`, `z₁ = ${format(nn.w1 * nn.x + 1)}`], answer: 0 },
    { title: 'Calculer la perte', text: 'Compare la prédiction à la cible y = 1. La perte mesure l’écart au carré.', values: [['ŷ', format(nn.prediction)], ['y', format(nn.target)], ['ŷ − y', format(nn.prediction - nn.target)]], question: `Avec ŷ = ${format(nn.prediction)} et y = 1, combien vaut L = ½(ŷ − y)² ?`, options: [`L = ${format(nn.loss)}`, `L = ${format(Math.abs(nn.prediction - nn.target))}`, `L = ${format(nn.prediction + nn.target)}`], answer: 0 },
    { title: 'Rétropropagation', text: 'Utilise la règle de chaîne pour calculer les gradients qui indiquent comment réduire la perte.', values: [['∂L/∂ŷ = ŷ − y', format(nn.prediction - nn.target)], ['∂L/∂w₂', format(nn.dw2)], ['∂L/∂w₁', format(nn.dw1)], ['∂L/∂b₁', format(nn.db1)]], question: `Sachant que ∂L/∂ŷ = ${format(nn.prediction - nn.target)} et h = ${format(nn.h)}, combien vaut ∂L/∂w₂ = (∂L/∂ŷ) × h ?`, options: [`∂L/∂w₂ = ${format(nn.dw2)}`, '∂L/∂w₂ = 0,1966', '∂L/∂w₂ = 0,7311'], answer: 0 },
    { title: 'Descente de gradient', text: 'Mets à jour les paramètres avec nouveau = ancien − η × gradient, en utilisant η = 0,1.', values: [['w₁ →', `${format(nn.w1)} → ${format(nn.updated.w1)}`], ['b₁ →', `${format(nn.b1)} → ${format(nn.updated.b1)}`], ['w₂ →', `${format(nn.w2)} → ${format(nn.updated.w2)}`], ['b₂ →', `${format(nn.b2)} → ${format(nn.updated.b2)}`]], question: `Avec w₂ = 1 et ∂L/∂w₂ = ${format(nn.dw2)}, quel est le nouveau w₂ ?`, options: [`w₂ = ${format(nn.updated.w2)}`, 'w₂ = 0,9803', 'w₂ = 1,1966'], answer: 0 },
    { title: 'Vérifier le résultat', text: 'Compare les valeurs avant et après la mise à jour pour vérifier que le calcul est cohérent.', values: [['ancienne prédiction', format(nn.prediction)], ['nouvelle prédiction', format(nn.newPrediction)], ['ancienne perte', format(nn.loss)], ['nouvelle perte', format(nn.newLoss)]], question: `Après la mise à jour, combien vaut la nouvelle prédiction ŷ ?`, options: [`ŷ = ${format(nn.newPrediction)}`, 'ŷ = 0,7311', 'ŷ = 1,1058'], answer: 0 },
  ]
  const [optionOrders, setOptionOrders] = useState(() => steps.map((item) => item.options.map((_, index) => index)))
  useEffect(() => {
    setOptionOrders(steps.map((item) => {
      const order = item.options.map((_, index) => index)
      for (let index = order.length - 1; index > 0; index -= 1) {
        const randomIndex = Math.floor(Math.random() * (index + 1))
        ;[order[index], order[randomIndex]] = [order[randomIndex], order[index]]
      }
      return order
    }))
  }, [])
  const currentStep = steps[step]
  const order = optionOrders[step]
  const current = { ...currentStep, options: order.map(index => currentStep.options[index]), answer: order.indexOf(currentStep.answer) }
  const selectedAnswer = answers[step]
  const correctOption = currentStep.options[currentStep.answer]
  const isCorrect = selectedAnswer === correctOption
  const choose = (option: string) => setAnswers(previous => ({ ...previous, [step]: option }))
  const nextStep = () => {
    if (isCorrect) setStep(currentStepIndex => Math.min(4, currentStepIndex + 1))
  }
  return <section id="learn" className="scroll-mt-6 space-y-5">
    <div className="flex items-start justify-between gap-4"><div><Badge className="mb-3 bg-blue-100 text-blue-700 hover:bg-blue-100">ACTIVITÉ 1 · PAS À PAS</Badge><h2 className="text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">Apprends à un réseau à corriger ses erreurs</h2><p className="mt-2 max-w-2xl text-muted-foreground">Pars d’un exemple minuscule, suis chaque opération, puis observe la mise à jour des quatre paramètres.</p></div><div className="hidden rounded-full bg-blue-50 p-3 text-blue-600 sm:block"><GitBranch /></div></div>
    <div className="grid gap-5 lg:grid-cols-[.9fr_1.1fr]">
      <Card className="border-slate-200 shadow-sm"><CardHeader><CardTitle className="flex items-center gap-2 text-base"><Network className="text-blue-600" /> Le réseau de départ</CardTitle><CardDescription>Paramètres : x = 2 · cible y = 1 · η = 0,1</CardDescription></CardHeader><CardContent className="space-y-4"><div className="rounded-xl border border-blue-100 bg-blue-50/60 p-3 font-mono text-sm leading-7 text-slate-700"><p><strong>Propagation :</strong> z = w × x + b</p><p><strong>Perte :</strong> L = ½(prediction − y)²</p><p><strong>Mise à jour :</strong> nouveau = ancien − η × gradient</p></div><NetworkDiagram state={{ ...trainLinear(.1, 0)[0], w: nn.w1, b: nn.b1, prediction: nn.prediction, loss: nn.loss, gradW: nn.dw1, gradB: nn.db1 }} /><div className="grid grid-cols-2 gap-2 text-sm"><Metric label="w₁ · poids caché" value="0,5000" /><Metric label="w₂ · poids sortie" value="1,0000" tone="violet" /><Metric label="b₁ · biais caché" value="0,0000" tone="orange" /><Metric label="b₂ · biais sortie" value="0,0000" tone="emerald" /></div></CardContent></Card>
      <Card className="border-slate-200 shadow-sm"><CardHeader><div className="flex items-center justify-between"><CardTitle className="text-base">Étape {step + 1} / 5 ��� {current.title}</CardTitle><Badge variant="outline">η = 0,1</Badge></div><Progress value={(step + 1) * 20} className="mt-3" /></CardHeader><CardContent className="space-y-5"><p className="text-sm leading-6 text-muted-foreground">{current.text}</p><div className="space-y-2">{current.values.map(([label, value], index) => <div key={label} className={`flex items-center justify-between rounded-lg border px-3 py-3 ${step === 2 && index === 0 ? 'border-violet-300 bg-violet-50' : 'bg-slate-50/70'}`}><span className="font-mono text-sm text-slate-700">{label}</span><span className="font-mono text-sm font-semibold text-slate-950">{value}</span></div>)}</div><div className="rounded-xl border border-violet-200 bg-violet-50/60 p-4"><p className="mb-3 text-sm font-semibold text-slate-900">Choisis la bonne réponse avant de continuer</p><div className="grid gap-2">{current.options.map((option, index) => <Button key={option} type="button" variant={selectedAnswer === option ? (isCorrect ? 'default' : 'destructive') : 'outline'} className="h-auto justify-start whitespace-normal py-2.5 text-left" onClick={() => choose(option)}>{selectedAnswer === option && isCorrect && <Check data-icon="inline-start" />}{option}</Button>)}</div>{selectedAnswer !== undefined && <p className={`mt-3 text-sm ${isCorrect ? 'text-emerald-700' : 'text-orange-700'}`}>{isCorrect ? 'Bonne réponse. Tu peux avancer.' : 'Ce n’est pas encore la bonne réponse, réessaie.'}</p>}</div><div className="flex items-center justify-between gap-3"><Button variant="outline" onClick={() => setStep(Math.max(0, step - 1))} disabled={step === 0}><ChevronLeft data-icon="inline-start" />Précédent</Button>{step < 4 ? <Button onClick={nextStep} disabled={!isCorrect}>Étape suivante<ChevronRight data-icon="inline-end" /></Button> : <div className="flex flex-wrap justify-end gap-2"><Button variant="outline" onClick={() => { setExerciseVersion(version => version + 1); setStep(0); setAnswers({}); setOptionOrders(steps.map(item => item.options.map((_, index) => index))); onRestart() }}>{language === 'fr' ? 'Faire un autre exercice' : language === 'en' ? 'Try another exercise' : language === 'es' ? 'Hacer otro ejercicio' : language === 'ar' ? 'تمرين آخر' : language === 'hi' ? 'एक और अभ्यास करें' : language === 'tr' ? 'Başka bir egzersiz' : 'Fazer outro exercício'}</Button><Button onClick={onContinue} disabled={!isCorrect} className="bg-violet-600 hover:bg-violet-700">Passer à l’expérience Python<ArrowRight data-icon="inline-end" /></Button></div>}</div></CardContent></Card>
    </div>
    <Alert className="border-blue-200 bg-blue-50/60"><Lightbulb className="text-blue-600" /><AlertTitle>Le fil rouge</AlertTitle><AlertDescription>Propagation avant → perte → rétropropagation → mise à jour. Dans l’activité suivante, le modèle est plus simple pour isoler exactement ce mécanisme.</AlertDescription></Alert>
  </section>
}

function CodeLab({ onRun, unlocked }: { onRun: (history: History) => void; unlocked: boolean }) {
  const [code, setCode] = useState(starterCode)
  const [message, setMessage] = useState('')
  const [params, setParams] = useState({ learningRate: .1, steps: 20 })
  const run = () => { const result = validateCode(code); if (!result.valid) return setMessage(result.message); const parsed = parseParameters(code); setParams({ learningRate: parsed.learningRate, steps: parsed.steps }); setMessage(result.message); onRun(trainLinear(parsed.learningRate, parsed.steps, parsed.w, parsed.b, parsed.x, parsed.y)) }
  return <section id="experiment" className="scroll-mt-6 space-y-5"><div><Badge className="mb-3 bg-violet-100 text-violet-700 hover:bg-violet-100">ACTIVITÉ 2 · SIMULATION</Badge> {!unlocked && <Alert className="mt-4 border-orange-200 bg-orange-50"><AlertDescription><strong>Exercice verrouillé :</strong> tu ne peux pas faire cet exercice tant que le réseau de départ n’est pas terminé. Termine les 5 étapes et leurs réponses avant de continuer.</AlertDescription></Alert>}<h2 className="text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">Maintenant, fais apprendre le modèle toi-même</h2><p className="mt-2 max-w-2xl text-muted-foreground">Modifie le programme, valide tes formules et exécute une <strong>simulation pédagogique Python</strong> déterministe.</p></div><Card className="overflow-hidden border-slate-200 shadow-sm"><div className="grid lg:grid-cols-[1.2fr_.8fr]"><div className="border-b bg-[#101827] p-4 lg:border-b-0 lg:border-r"><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-2 text-sm font-medium text-slate-200"><Code2 className="text-violet-300" /> exercice.py</div><Badge variant="outline" className="border-violet-400/40 bg-violet-400/10 text-violet-200">Simulation pédagogique Python</Badge></div><Textarea value={code} onChange={e => setCode(e.target.value)} aria-label="Code Python de l'exercice" className="min-h-[390px] resize-y border-slate-700 bg-slate-950 font-mono text-[13px] leading-6 text-slate-200 placeholder:text-slate-500 focus-visible:ring-violet-400" spellCheck={false} /><div className="mt-3 flex flex-wrap gap-2"><Button onClick={run} className="bg-violet-500 text-white hover:bg-violet-600"><Play data-icon="inline-start" />Exécuter</Button><Button variant="outline" onClick={() => setCode(starterCode)} className="border-slate-600 bg-transparent text-slate-200 hover:bg-slate-800"><RotateCcw data-icon="inline-start" />Réinitialiser le code</Button><Button variant="ghost" onClick={() => setMessage('Indice : vérifie prediction, loss, grad_w, grad_b et les deux formules de mise à jour.')} className="text-slate-300"><Lightbulb data-icon="inline-start" />Indice</Button></div></div><div className="space-y-5 p-5"><div><p className="text-sm font-semibold text-slate-900">Paramètres du programme</p><p className="mt-1 text-xs text-muted-foreground">Les valeurs sont lues depuis ton code pour garder les résultats synchronisés.</p></div><div className="grid grid-cols-2 gap-3"><Metric label="x" value="2,0000" /><Metric label="y" value="1,0000" tone="violet" /></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-1"><label className="grid gap-1 text-sm"><span className="text-muted-foreground">Taux d’apprentissage</span><Input type="number" min="0.001" max="2" step="0.01" value={params.learningRate} onChange={e => { const v = Number(e.target.value); setParams(p => ({ ...p, learningRate: v })); setCode(c => c.replace(/learning_rate\s*=\s*(-?[0-9.]+)/, `learning_rate = ${v}`)) }} /></label><label className="grid gap-1 text-sm"><span className="text-muted-foreground">Étapes d’entraînement</span><Input type="number" min="1" max="100" value={params.steps} onChange={e => { const v = Number(e.target.value); setParams(p => ({ ...p, steps: v })); setCode(c => c.replace(/training_steps\s*=\s*(-?[0-9.]+)/, `training_steps = ${v}`)) }} /></label></div>{message && <Alert className={message.startsWith('Code reconnu') ? 'border-emerald-200 bg-emerald-50' : 'border-orange-200 bg-orange-50'}><AlertDescription>{message}</AlertDescription></Alert>}<div className="rounded-xl bg-slate-50 p-4 text-sm leading-6 text-muted-foreground"><p className="font-medium text-slate-800">Pourquoi une simulation ?</p><p className="mt-1">L’éditeur accepte ce programme précis et calcule ses résultats avec le même moteur TypeScript que les graphiques. Aucun code arbitraire n’est exécuté dans le navigateur.</p></div></div></div></Card></section>
}

function TrainingLab({ history, learningRate, setLearningRate }: { history: History; learningRate: number; setLearningRate: (v: number) => void }) {
  const [selected, setSelected] = useState(history.length - 1)
  const [playing, setPlaying] = useState(false)
  useEffect(() => {
    setSelected(history.length - 1)
    setPlaying(false)
  }, [history])
  useEffect(() => { if (!playing) return; const timer = window.setInterval(() => setSelected(s => { if (s >= history.length - 1) { setPlaying(false); return s } return s + 1 }), 700); return () => window.clearInterval(timer) }, [playing, history.length])
  const state = history[selected]
  const status = history.at(-1)!.loss < history[0].loss ? 'Le modèle apprend : sa prédiction se rapproche de la cible et sa perte diminue.' : 'La perte augmente : ce taux est peut-être trop élevé, le modèle dépasse la bonne direction.'
  return <section id="visualize" className="scroll-mt-6 space-y-5"><div className="flex flex-wrap items-end justify-between gap-4"><div><Badge className="mb-3 bg-orange-100 text-orange-700 hover:bg-orange-100">LABORATOIRE · VUE INTERNE</Badge><h2 className="text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">Visualise chaque mise à jour</h2><p className="mt-2 max-w-2xl text-muted-foreground">Sélectionne un instant : le diagramme, les métriques et l’historique utilisent exactement le même état calculé.</p></div><div className="flex items-center gap-2 rounded-xl border bg-white p-2"><Button size="icon" variant="outline" onClick={() => setSelected(Math.max(0, selected - 1))} aria-label="Étape précédente"><ChevronLeft /></Button><Button size="icon" onClick={() => setPlaying(v => !v)} aria-label={playing ? 'Pause' : 'Lecture'}>{playing ? <Pause /> : <Play />}</Button><Button size="icon" variant="outline" onClick={() => setSelected(Math.min(history.length - 1, selected + 1))} aria-label="Étape suivante"><ChevronRight /></Button><Button size="sm" variant="ghost" onClick={() => setSelected(0)}><RotateCcw data-icon="inline-start" />Recommencer</Button></div></div>
    <NetworkDiagram state={state} />
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-8"><Metric label="étape" value={`${state.step}`} tone="violet" /><Metric label="prédiction" value={format(state.prediction)} tone="blue" /><Metric label="perte" value={format(state.loss)} tone="orange" /><Metric label="erreur" value={format(state.prediction - 1)} tone="orange" /><Metric label="gradient w" value={format(state.gradW)} tone="violet" /><Metric label="gradient b" value={format(state.gradB)} tone="violet" /><Metric label="poids w" value={format(state.w)} tone="emerald" /><Metric label="biais b" value={format(state.b)} tone="emerald" /></div>
    <Card className="border-slate-200 shadow-sm"><CardContent className="space-y-3 pt-6"><div className="flex items-center justify-between text-sm"><span className="font-medium">Étape inspectée : {state.step} / {history.length - 1}</span><span className="text-muted-foreground">vitesse : 0,7 s</span></div><Slider value={[selected]} min={0} max={history.length - 1} step={1} onValueChange={v => setSelected(Array.isArray(v) ? v[0] : v)} aria-label="Étape d'entraînement" /></CardContent></Card>
    <Alert className={history.at(-1)!.loss < history[0].loss ? 'border-emerald-200 bg-emerald-50' : 'border-orange-200 bg-orange-50'}><TrendingDown className="text-emerald-600" /><AlertDescription>{status}</AlertDescription></Alert>
    <div className="grid gap-5 xl:grid-cols-3"><ChartCard title="Perte par étape" data={history} dataKey="loss" color="var(--color-loss)" type="area" /><ChartCard title="Prédiction et cible" data={history.map(s => ({ ...s, target: 1 }))} dataKey="prediction" color="var(--color-prediction)" target /><ChartCard title="Poids et biais" data={history} dataKey="w" color="var(--color-weight)" bias /></div>
    <Card className="border-slate-200 shadow-sm"><CardHeader><CardTitle className="text-base">Historique d’entraînement</CardTitle><CardDescription>Clique sur une ligne pour inspecter cet état dans le réseau.</CardDescription></CardHeader><CardContent><div className="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>Étape</TableHead><TableHead>Prédiction</TableHead><TableHead>Perte</TableHead><TableHead>Poids</TableHead><TableHead>Biais</TableHead><TableHead>Gradient w</TableHead></TableRow></TableHeader><TableBody>{history.filter((_, i) => i === 0 || i % 2 === 0 || i === history.length - 1).map(row => <TableRow key={row.step} className={`cursor-pointer ${row.step === selected ? 'bg-violet-50' : ''}`} onClick={() => setSelected(row.step)}><TableCell className="font-medium">{row.step === 0 ? 'Init.' : row.step}</TableCell><TableCell>{format(row.prediction)}</TableCell><TableCell>{format(row.loss)}</TableCell><TableCell>{format(row.w)}</TableCell><TableCell>{format(row.b)}</TableCell><TableCell className="text-violet-700">{format(row.gradW)}</TableCell></TableRow>)}</TableBody></Table></div></CardContent></Card>
    <RateComparison active={learningRate} onSelect={setLearningRate} />
  </section>
}

function ChartCard({ title, data, dataKey, color, type, target, bias }: { title: string; data: History | (History[number] & { target: number })[]; dataKey: string; color: string; type?: string; target?: boolean; bias?: boolean }) {
  return <Card className="min-w-0 border-slate-200 shadow-sm"><CardHeader className="pb-2"><CardTitle className="text-sm">{title}</CardTitle></CardHeader><CardContent className="h-56 pl-1 pr-4"><ResponsiveContainer width="100%" height="100%"><LineChart data={data}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" /><XAxis dataKey="step" tickLine={false} axisLine={false} fontSize={11} /><YAxis tickLine={false} axisLine={false} fontSize={11} width={36} /><ChartTooltip contentStyle={{ borderRadius: 10, border: '1px solid #e2e8f0', fontSize: 12 }} /><Line type="monotone" dataKey={dataKey} stroke={color} strokeWidth={2.5} dot={false} /><>{target && <Line type="monotone" dataKey="target" stroke="#94a3b8" strokeDasharray="4 4" dot={false} />}{bias && <Line type="monotone" dataKey="b" stroke="var(--color-bias)" strokeWidth={2} dot={false} />}</></LineChart></ResponsiveContainer></CardContent></Card>
}

function RateComparison({ active, onSelect }: { active: number; onSelect: (v: number) => void }) { const rates = [.01, .1, .5]; const series = rates.map(rate => ({ rate, history: trainLinear(rate, 20) })); return <Card className="border-slate-200 shadow-sm"><CardHeader><div className="flex flex-wrap items-center justify-between gap-3"><div><CardTitle className="text-base">Comparer les trois taux</CardTitle><CardDescription>Mêmes paramètres de départ, trois tailles de pas différentes.</CardDescription></div><Button variant="outline" size="sm" onClick={() => onSelect(.1)}><Gauge data-icon="inline-start" />Taux intermédiaire</Button></div></CardHeader><CardContent><div className="grid gap-4 lg:grid-cols-[.8fr_1.2fr]"><div className="grid gap-2 sm:grid-cols-3 lg:grid-cols-1">{series.map(({ rate, history }) => <button key={rate} onClick={() => onSelect(rate)} className={`rounded-xl border p-3 text-left transition-colors ${active === rate ? 'border-violet-400 bg-violet-50' : 'hover:bg-slate-50'}`}><div className="flex items-center justify-between"><span className="font-mono font-semibold">η = {rate}</span><Badge variant="outline">{rate === .01 ? 'lent' : rate === .1 ? 'équilibré' : 'rapide'}</Badge></div><p className="mt-1 text-xs text-muted-foreground">perte finale : {format(history.at(-1)!.loss)}</p></button>)}</div><div className="h-64"><ResponsiveContainer width="100%" height="100%"><LineChart><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" /><XAxis dataKey="step" type="number" domain={[0, 20]} tickLine={false} axisLine={false} fontSize={11} /><YAxis tickLine={false} axisLine={false} fontSize={11} /><ChartTooltip contentStyle={{ borderRadius: 10, fontSize: 12 }} />{series.map(({ rate, history }, i) => <Line key={rate} data={history} type="monotone" dataKey="loss" name={`η ${rate}`} stroke={['#94a3b8', '#7c3aed', '#f97316'][i]} strokeWidth={rate === active ? 3 : 1.5} dot={false} />)}</LineChart></ResponsiveContainer></div></div><p className="mt-4 text-sm text-muted-foreground">Un taux plus élevé n’est pas automatiquement meilleur : il peut accélérer l’apprentissage, mais aussi créer du dépassement ou de l’instabilité.</p></CardContent></Card> }

function QuizSection() { const [answers, setAnswers] = useState<number[]>([]); const score = answers.filter((a, i) => a === quiz[i]?.answer).length; return <section id="quiz" className="scroll-mt-6 space-y-5"><div><Badge className="mb-3 bg-emerald-100 text-emerald-700 hover:bg-emerald-100">ÉTAPE FINALE · QUIZ</Badge><h2 className="text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">Vérifie tes connaissances</h2><p className="mt-2 max-w-2xl text-muted-foreground">Cinq questions pour consolider le lien entre les calculs et l’intuition.</p></div><div className="grid gap-4">{quiz.map((item, i) => { const selected = answers[i]; const answered = selected !== undefined; return <Card key={item.question} className="border-slate-200 shadow-sm"><CardHeader><div className="flex items-start gap-3"><div className="grid size-8 shrink-0 place-items-center rounded-full bg-slate-100 text-sm font-semibold">{i + 1}</div><CardTitle className="text-base leading-6">{item.question}</CardTitle></div></CardHeader><CardContent className="space-y-3"><div className="grid gap-2 sm:grid-cols-3">{item.options.map((option, oi) => <Button key={option} variant={selected === oi ? (oi === item.answer ? 'default' : 'destructive') : 'outline'} className="h-auto justify-start whitespace-normal py-3 text-left" onClick={() => setAnswers(a => { const next = [...a]; next[i] = oi; return next })}>{selected === oi && oi === item.answer && <Check data-icon="inline-start" />}{option}</Button>)}</div>{answered && <p className={`text-sm ${selected === item.answer ? 'text-emerald-700' : 'text-orange-700'}`}>{selected === item.answer ? 'Bonne réponse. ' : 'Pas tout à fait. '}{item.explanation}</p>}</CardContent></Card>})}</div>{answers.length === quiz.length && <Alert className="border-emerald-200 bg-emerald-50"><Trophy className="text-emerald-600" /><AlertDescription><strong>Score : {score} / {quiz.length}.</strong> {score >= 4 ? 'Excellent travail, les mécanismes essentiels sont en place.' : 'Relis les étapes puis essaie encore pour consolider les notions.'}</AlertDescription></Alert>}</section> }

